    private static string RegexProfileOperatorProgram(string literalPattern, string stringPattern)
    {
        var program = new System.Text.StringBuilder("BEGIN{");
        foreach (var probe in RegexProfileProbes1)
            program.Append("print (").Append(probe).Append(" ~ ").Append(literalPattern)
                .Append("),(").Append(probe).Append(" ~ ").Append(stringPattern).Append(");");
        return program.Append('}').ToString();
    }

    // Probe values are awk source literals; preserve their original escape spelling.
    private static string RegexProfileMatchProgram(string prefix, string statement, string[] probes, bool terminateLast)
    {
        var program = new System.Text.StringBuilder("BEGIN{").Append(prefix);
        for (var index = 0; index < probes.Length; index++)
            program.Append("s=").Append(probes[index]).Append(';')
                .Append(index == probes.Length - 1 && !terminateLast ? statement.TrimEnd(';') : statement);
        return program.Append('}').ToString();
    }
